package io.github.grillza.icreader.icon

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import androidx.annotation.ColorRes
import androidx.annotation.DrawableRes

/** A launcher icon: one <activity-alias> in the manifest, generated by tools/gen_icons.py. */
data class AppIcon(
    val id: String,
    val label: String,
    val component: String,
    @param:DrawableRes val foreground: Int,
    @param:ColorRes val background: Int,
)

/**
 * Switches the launcher icon by enabling one activity-alias and disabling the rest. Launchers can
 * take a few seconds to refresh, and some drop home-screen shortcuts to the old alias.
 *
 * Disabling the alias that launched the running task makes Android close that task, so a change
 * is only queued by [request] and applied by [applyPending] once the app leaves the foreground.
 */
class AppIconManager(private val context: Context) {

    private val pm get() = context.packageManager
    private val prefs by lazy { context.getSharedPreferences("app_icon", Context.MODE_PRIVATE) }

    /** The icon the user picked, even if it hasn't been applied yet. */
    fun current(): AppIcon =
        prefs.getString(KEY_PENDING, null)?.let(::forId)
            ?: APP_ICONS.firstOrNull { isEnabled(it) }
            ?: APP_ICONS.first()

    fun forId(id: String): AppIcon? = APP_ICONS.firstOrNull { it.id == id }

    fun request(id: String) {
        prefs.edit().putString(KEY_PENDING, id).apply()
    }

    /**
     * Set while we've sent the user to another screen we expect them back from (photo picker,
     * share sheet, settings), so leaving for it doesn't apply the change and close the task.
     */
    @Volatile var hold = false

    fun applyPending() {
        if (hold) return
        val id = prefs.getString(KEY_PENDING, null) ?: return
        prefs.edit().remove(KEY_PENDING).apply()
        select(id)
    }

    private fun select(id: String) {
        val target = forId(id) ?: return
        // Enable the new alias before disabling the others so there is always a launcher entry.
        setEnabled(target, true)
        APP_ICONS.filter { it.id != target.id }.forEach { setEnabled(it, false) }
    }

    private fun isEnabled(icon: AppIcon): Boolean =
        when (pm.getComponentEnabledSetting(component(icon))) {
            PackageManager.COMPONENT_ENABLED_STATE_ENABLED -> true
            PackageManager.COMPONENT_ENABLED_STATE_DEFAULT -> icon.id == APP_ICONS.first().id
            else -> false
        }

    private fun setEnabled(icon: AppIcon, enabled: Boolean) {
        if (isEnabled(icon) == enabled) return
        pm.setComponentEnabledSetting(
            component(icon),
            if (enabled) PackageManager.COMPONENT_ENABLED_STATE_ENABLED else PackageManager.COMPONENT_ENABLED_STATE_DISABLED,
            PackageManager.DONT_KILL_APP,
        )
    }

    private fun component(icon: AppIcon) = ComponentName(context.packageName, icon.component)

    private companion object {
        const val KEY_PENDING = "pending"
    }
}
